-- Gold Query
SELECT DISTINCT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t2.finishing = 1 ORDER BY t1.birthday ASC, t1.player_name NULLS LAST LIMIT 1;

/*
Gold Result:
('Allison Hill',)
*/

-- Prediction Query
SELECT p.player_name FROM Player AS p JOIN Player_Attributes AS pa ON p.player_api_id = pa.player_api_id WHERE pa.finishing = 1 AND STRFTIME('%Y', pa.date) - STRFTIME('%Y', p.birthday) = (SELECT MAX(STRFTIME('%Y', pa2.date) - STRFTIME('%Y', p2.birthday)) FROM Player AS p2 JOIN Player_Attributes AS pa2 ON p2.player_api_id = pa2.player_api_id WHERE pa2.finishing = 1);

